// PI_SAVE v20 "Prepare": v19's Check Doc No -> Required Fields -> CHECK_REQUIRED_FIELD -> Check Invoice Qty -> Fillback chain in
// one node, so a 2,000-line invoice is copied once instead of eight times. Each step is the old node's code; its result goes
// through the same output filter the platform applied between the old nodes.
const piPrep = function piPrep(data, systemTenantId) {
  const plat = (v) => {
    if (Array.isArray(v)) return v.map(plat);
    if (v && typeof v === "object") {
      const o = {};
      for (const k of Object.keys(v)) if (v[k] !== null && v[k] !== undefined) o[k] = plat(v[k]);
      return o;
    }
    return v;
  };
  const copy = (v) => (v === undefined ? null : JSON.parse(JSON.stringify(v)));
  const ph = (v) => (v === undefined ? null : v);
  const fail = (route, message) => ({ route: route, message: message, entry: {}, isCompleted: "0", needPo: "0", needGr: "0",
    poIdsSql: "0", grIdsSql: "0", piIdSql: "0", piId: null, tenantId: "0", check: {} });

  // CHECK_REQUIRED_FIELD (1988831880511062018) v8
  const validateField = (value, field) => {
    if (value === undefined || value === null) return true;
    if (typeof value === "string") return value.trim() === "";
    if (typeof value === "number") return value <= 0;
    if (Array.isArray(value)) return value.length === 0;
    if (typeof value === "object") return Object.keys(value).length === 0;
    return !value;
  };
  const validateForm = (entry, requiredFields) => {
    const missingFields = [];
    requiredFields.forEach((field) => {
      const value = entry[field.name];
      if (!field.isArray) {
        if (validateField(value, field)) missingFields.push(field.label);
        return;
      }
      if (!Array.isArray(value)) {
        missingFields.push(`${field.label}`);
        return;
      }
      if (value.length === 0) {
        missingFields.push(`${field.label}`);
        return;
      }
      if (field.arrayType === "object" && field.arrayFields && value.length > 0) {
        value.forEach((item, index) => {
          field.arrayFields.forEach((subField) => {
            if (validateField(item[subField.name], subField)) missingFields.push(`${subField.label} (in ${field.label} #${index + 1})`);
          });
        });
      }
    });
    return missingFields;
  };
  const required = (fields, values) => {
    const missingFields = validateForm(JSON.parse(JSON.stringify(values)), fields);
    return missingFields.length === 0 ? "" : "Validation Error: " + missingFields.join(", ");
  };

  const bundleKey = (row) => {
    const bundle = row.item_bundle_id;
    if (bundle && typeof bundle === "object") return String(bundle.id || bundle.ib_no || "");
    return String(bundle || "");
  };
  const flattenWithParent = (rows, itemKey) => {
    const flat = [];
    const positionOf = new Map();
    const isBundleRow = (row) => Boolean(bundleKey(row)) && !row[itemKey];
    const isBundleItem = (row) => Boolean(bundleKey(row)) && Boolean(row[itemKey]);
    let openBundle = -1;
    for (const [index, row] of (rows || []).entries()) {
      const position = flat.length;
      positionOf.set(index, position);
      const children = Array.isArray(row.children) ? row.children : [];
      if (children.length > 0) {
        openBundle = -1;
        flat.push({ row, parent: -1, nested: false });
        for (const child of children) flat.push({ row: child, parent: position, nested: true });
        continue;
      }
      if (isBundleRow(row)) {
        openBundle = position;
        flat.push({ row, parent: -1, nested: false });
        continue;
      }
      if (!isBundleItem(row)) {
        openBundle = -1;
        flat.push({ row, parent: -1, nested: false });
        continue;
      }
      let parent = -1;
      for (let candidate = index - 1; candidate >= 0; candidate--) {
        const candidateRow = rows[candidate];
        if (!isBundleRow(candidateRow)) continue;
        const byId = row.parent_id != null && candidateRow.id != null && String(row.parent_id) === String(candidateRow.id);
        const byKey = row.parent_fm_key != null && candidateRow.fm_key != null && String(row.parent_fm_key) === String(candidateRow.fm_key);
        if (byId || byKey) {
          parent = positionOf.get(candidate);
          break;
        }
      }
      if (parent === -1 && openBundle !== -1 && bundleKey(flat[openBundle].row) === bundleKey(row)) parent = openBundle;
      flat.push({ row, parent, nested: false });
    }
    return flat;
  };

  // Check Invoice Qty (code_pi_checkqty)
  const checkQty = (entry) => {
    const flat = flattenWithParent(entry.table_pi, "material_id");
    const totalQuantity = flat.reduce((sum, item) => {
      const { invoice_qty } = item.row;
      const positiveQty = Math.abs(invoice_qty);
      return sum + (positiveQty || 0);
    }, 0);
    if (totalQuantity === 0) return null;
    const dropped = new Set();
    for (const [position, item] of flat.entries()) {
      if (item.row.invoice_qty !== 0) continue;
      dropped.add(position);
      if (item.parent !== -1) continue;
      for (const [childPosition, candidate] of flat.entries()) if (candidate.parent === position) dropped.add(childPosition);
    }
    // the bundle items of each kept row, in order (v19 scanned every row per row)
    const nestedUnder = new Map();
    for (const [childPosition, candidate] of flat.entries()) {
      if (dropped.has(childPosition) || !candidate.nested) continue;
      if (!nestedUnder.has(candidate.parent)) nestedUnder.set(candidate.parent, []);
      nestedUnder.get(candidate.parent).push(candidate.row);
    }
    const keptRows = [];
    for (const [position, item] of flat.entries()) {
      if (dropped.has(position) || item.nested) continue;
      const children = nestedUnder.get(position) || [];
      if (children.length > 0) keptRows.push({ ...item.row, children });
      else if (Array.isArray(item.row.children)) keptRows.push({ ...item.row, children: [] });
      else keptRows.push(item.row);
    }
    entry.table_pi = keptRows;
    let poID = [];
    let grID = [];
    let purchaseOrderNumber = [];
    let goodsReceivingNumber = [];
    for (const [position, item] of flat.entries()) {
      if (dropped.has(position)) continue;
      const pi = item.row;
      if (pi.line_gr_id && pi.line_gr_id !== "") {
        grID.push(pi.line_gr_id);
        goodsReceivingNumber.push(pi.goods_receiving_no);
      }
      poID.push(pi.line_po_id);
      purchaseOrderNumber.push(pi.purchase_order_no);
    }
    entry.po_id = [...new Set(poID)];
    entry.gr_id = [...new Set(grID)];
    entry.po_no_display = [...new Set(purchaseOrderNumber)].join(", ");
    entry.gr_no_display = [...new Set(goodsReceivingNumber)].join(", ");
    return entry;
  };

  // Fillback Header Fields (code_pi_fillback)
  const fillback = (entry) => {
    const stampPiLineItem = (piLineItem) => {
      piLineItem.supplier_id = entry.supplier_name || null;
      piLineItem.plant_id = entry.plant_id || null;
      piLineItem.payment_term_id = entry.invoice_payment_term_id || null;
      piLineItem.billing_state_id = entry.billing_address_state || null;
      piLineItem.billing_country_id = entry.billing_address_country || null;
      piLineItem.shipping_state_id = entry.shipping_address_state || null;
      piLineItem.shipping_country_id = entry.shipping_address_country || null;
      piLineItem.agent_id = entry.agent_id;
    };
    const flat = flattenWithParent(entry.table_pi, "material_id");
    const itemsNumbered = new Map();
    let lineNumber = 0;
    for (const item of flat) {
      stampPiLineItem(item.row);
      if (item.parent === -1) {
        lineNumber++;
        item.row.line_index = lineNumber;
        continue;
      }
      const childNumber = (itemsNumbered.get(item.parent) || 0) + 1;
      itemsNumbered.set(item.parent, childNumber);
      item.row.line_index = `${flat[item.parent].row.line_index}-${childNumber}`;
    }
    entry.posted_status = entry.pi_status === "Draft" ? "" : "Unposted";
    return entry;
  };

  let entry;
  if (data && data.pi_status === "Draft") {
    let table = copy(data);
    if (table.purchase_invoice_no_type !== -9999 && (!table.purchase_invoice_no || table.purchase_invoice_no === null || table.purchase_invoice_no === "")) {
      table.purchase_invoice_no = "draft";
    }
    table.pi_status = "Draft";
    table = plat(table);
    const missing = required([
      { name: "plant_id", label: "Plant" },
      { name: "purchase_invoice_no", label: "Purchase Invoice Number" },
      { name: "table_pi", label: "Item Information", isArray: true, arrayType: "object", arrayFields: [] },
    ], { plant_id: ph(table.plant_id), purchase_invoice_no: ph(table.purchase_invoice_no), table_pi: ph(table.table_pi) });
    if (missing) return fail("E406", missing);
    entry = table;
  } else {
    let table = copy(data);
    if (table.purchase_invoice_no_type !== -9999 && (!table.purchase_invoice_no || table.purchase_invoice_no === null || table.purchase_invoice_no === "" ||
      table.previous_status === "Draft")) {
      table.purchase_invoice_no = "issued";
    }
    table.pi_status = "Completed";
    table = plat(table);
    const missing = required([
      { name: "plant_id", label: "Plant" },
      { name: "purchase_invoice_no", label: "Purchase Invoice Number" },
      { name: "invoice_date", label: "Invoice Date" },
      { name: "pi_description", label: "Description" },
      { name: "table_pi", label: "PI Items", isArray: true, arrayType: "object", arrayFields: [] },
    ], { plant_id: ph(table.plant_id), purchase_invoice_no: ph(table.purchase_invoice_no), invoice_date: ph(table.invoice_date),
      pi_description: ph(table.pi_description), table_pi: ph(table.table_pi) });
    if (missing) return fail("E406", missing);
    entry = checkQty(table);
    if (!entry) return fail("E407", "Total invoiced quantity is 0.");
    entry = plat(entry);
  }
  entry = plat(fillback(entry));

  // What the over-invoice check and the PO / GR roll-up read off the lines, keeping the tree as it is
  const LINE_KEYS = ["id", "line_po_id", "line_gr_id", "po_line_id", "gr_line_id", "invoice_qty", "material_id", "material_name", "item_bundle_id",
    "parent_id", "fm_key", "parent_fm_key"];
  const compact = (row) => {
    const out = {};
    if (!row || typeof row !== "object") return out;
    for (const k of LINE_KEYS) if (Object.prototype.hasOwnProperty.call(row, k)) out[k] = row[k];
    if (Array.isArray(row.children)) out.children = row.children.map(compact);
    return out;
  };
  const idsSql = (v) => {
    const ids = (Array.isArray(v) ? v : [v]).map((x) => (x === undefined || x === null ? "" : String(x).trim())).filter((x) => /^[0-9]{1,20}$/.test(x));
    return ids.length ? [...new Set(ids)].join(",") : "0";
  };
  const isCompleted = entry.pi_status === "Completed";
  const tenantId = systemTenantId === undefined || systemTenantId === null ? "" : String(systemTenantId);
  const poIdsSql = idsSql(entry.po_id);
  const grIdsSql = entry.gr_id && entry.gr_id.length > 0 ? idsSql(entry.gr_id) : "0";
  const rawId = entry.id === undefined || entry.id === null ? "" : String(entry.id).trim();
  return {
    route: "OK",
    message: "",
    entry: entry,
    isCompleted: isCompleted ? "1" : "0",
    needPo: isCompleted && poIdsSql !== "0" ? "1" : "0",
    needGr: isCompleted && grIdsSql !== "0" ? "1" : "0",
    poIdsSql: poIdsSql,
    grIdsSql: grIdsSql,
    piIdSql: /^[0-9]{1,20}$/.test(rawId) ? rawId : "0",
    piId: entry.id === undefined ? null : entry.id,
    tenantId: /^[0-9]{1,20}$/.test(tenantId) ? tenantId : "0",
    check: isCompleted ? { po_id: entry.po_id, gr_id: entry.gr_id, table_pi: (entry.table_pi || []).map(compact) } : {},
  };
};

return piPrep({{workflowparams:data}}, [{{system:tenantId}}][0]);

SELECT JSON_OBJECT('id', CAST(p.id AS CHAR), 'pi_status', p.pi_status, 'purchase_invoice_no', p.purchase_invoice_no) AS j
  FROM purchase_invoice p
 WHERE p.tenant_id = '{{node:code_pi_prep.data.tenantId}}' AND p.is_deleted = 0 AND p.id = {{node:code_pi_prep.data.piIdSql}}

// PI_SAVE v20 "Stored PI Still Draft?": v19's guard, reading the stored invoice's status and number from a sql-node
const piGuard = function piGuard(piId, storedRows) {
  const parseJ = (t) => {
    if (t && typeof t === "object") return t;
    try {
      return JSON.parse(String(t).replace(/"(?:[^"\\]|\\.)*"|-?\d{16,}(?![.\deE])/g, (m) => (m[0] === '"' ? m : '"' + m + '"')));
    } catch (e) {
      return null;
    }
  };
  const stored = (Array.isArray(storedRows) ? storedRows : []).map((r) => parseJ(r && r.j !== undefined ? r.j : r));
  const record = stored.find((row) => row && String(row.id) === String(piId));
  const storedStatus = record ? String(record.pi_status || "") : "";
  const blocked = storedStatus !== "" && storedStatus !== "Draft";
  return {
    blocked: blocked ? 1 : 0,
    message: blocked
      ? `Purchase Invoice ${record.purchase_invoice_no || ""} is already ${storedStatus}, so it was not saved again. Close and reopen it to see its current state.`
      : "",
  };
};

return piGuard([{{node:code_pi_prep.data.piId}}][0], [{{node:sql_node_pi_stored.data}}][0]);

// PI_SAVE v20 "Check and roll up": v19's over-invoice check (code_pi_validate) and PO / GR roll-up (code_pi_apply) in one node,
// run before the invoice is written. The orders and receipts come from sql-nodes that read only the columns these two use; they
// are put back into the shape the old search nodes gave (null and "" keys left off, a bundle's items under `children`).
const piParseJ = function piParseJ(t) {
  if (t && typeof t === "object") return t;
  try {
    return JSON.parse(String(t).replace(/"(?:[^"\\]|\\.)*"|-?\d{16,}(?![.\deE])/g, (m) => (m[0] === '"' ? m : '"' + m + '"')));
  } catch (e) {
    return null;
  }
};
const piShape = function piShape(rows, lineKey) {
  const docs = [];
  const byDoc = new Map();
  for (const r of Array.isArray(rows) ? rows : []) {
    const o = piParseJ(r && r.j !== undefined ? r.j : r);
    if (!o || !o.doc) continue;
    if (!byDoc.has(o.doc)) {
      const doc = { id: o.doc, lines: [] };
      byDoc.set(o.doc, doc);
      docs.push(doc);
    }
    if (o.id === undefined || o.id === null || o.id === "") continue;
    const line = {};
    for (const k of Object.keys(o)) if (k !== "doc" && o[k] !== null && o[k] !== undefined && o[k] !== "") line[k] = o[k];
    byDoc.get(o.doc).lines.push(line);
  }
  return docs.map((doc) => {
    const ids = new Set(doc.lines.map((l) => String(l.id)));
    const kids = new Map();
    for (const l of doc.lines) {
      if (l.parent_id === undefined || !ids.has(String(l.parent_id))) continue;
      if (!kids.has(String(l.parent_id))) kids.set(String(l.parent_id), []);
      kids.get(String(l.parent_id)).push(l);
    }
    const top = doc.lines.filter((l) => l.parent_id === undefined || !ids.has(String(l.parent_id)));
    const tree = top.map((l) => (kids.has(String(l.id)) ? Object.assign({}, l, { children: kids.get(String(l.id)) }) : l));
    return { id: doc.id, [lineKey]: tree };
  });
};
const piCheck = function piCheck(data, poRows, grRows) {
  const poList = piShape(poRows, "table_po");
  const grList = piShape(grRows, "table_gr");

  // ---- code_pi_validate (v19) ----
  let allErrors = [];
  const flattenRows = (rows) => {
    const flat = [];
    for (const row of rows || []) {
      flat.push(row);
      const children = Array.isArray(row.children) ? row.children : [];
      for (const child of children) flat.push(child);
    }
    return flat;
  };
  const round8 = (value) => Math.round((parseFloat(value) || 0) * 100000000) / 100000000;
  const validateInvoiceQuantities = (items, tablePi, docId, docIdKey, piLineIdKey, qtyKey, excludeGRLines) => {
    const filteredPI = tablePi.filter((item) => item[docIdKey] === docId && (!excludeGRLines || !item.line_gr_id || item.line_gr_id === ""));
    const errors = [];
    const byId = new Map();
    for (const item of items) if (!byId.has(item.id)) byId.set(item.id, item);
    filteredPI.forEach((piItem) => {
      const originalItem = byId.get(piItem[piLineIdKey]);
      if (originalItem) {
        const availableQty = round8(originalItem[qtyKey]);
        const currentInvoicedQty = round8(originalItem.invoice_qty);
        const newInvoiceQty = round8(piItem.invoice_qty);
        const totalInvoicedQty = round8(currentInvoicedQty + newInvoiceQty);
        if (totalInvoicedQty > availableQty) {
          errors.push({ itemName: originalItem.material_id || originalItem.material_name || `Item ${originalItem.id}` });
        }
      }
    });
    if (!excludeGRLines) {
      filteredPI.forEach((piItem) => {
        if ((piItem.gr_line_id && piItem.gr_line_id !== "") || !piItem.po_line_id) return;
        const groupRows = items.filter((item) => item.parent_or_child === "Split-Parent" && item.po_line_item_id === piItem.po_line_id);
        if (groupRows.length === 0) return;
        const totalRemaining = round8(groupRows.reduce((sum, item) => sum + ((parseFloat(item.received_qty) || 0) - (parseFloat(item.invoice_qty) || 0)), 0));
        if (round8(piItem.invoice_qty) > totalRemaining) {
          errors.push({ itemName: piItem.material_id || piItem.material_name || `Item ${piItem.po_line_id}` });
        }
      });
    }
    return errors;
  };
  const poIds = Array.isArray(data.po_id) ? data.po_id : [data.po_id];
  for (const poID of poIds) {
    const poData = poList.find((po) => po.id === poID);
    if (!poData) continue;
    const poItems = flattenRows(poData.table_po || []);
    allErrors = [...allErrors, ...validateInvoiceQuantities(poItems, flattenRows(data.table_pi), poData.id, "line_po_id", "po_line_id", "quantity", true)];
  }
  if (data.gr_id && data.gr_id.length > 0) {
    const grIds = Array.isArray(data.gr_id) ? data.gr_id : [data.gr_id];
    for (const grID of grIds) {
      const grData = grList.find((gr) => gr.id === grID);
      if (!grData) continue;
      const grItems = flattenRows(grData.table_gr || []);
      allErrors = [...allErrors, ...validateInvoiceQuantities(grItems, flattenRows(data.table_pi), grData.id, "line_gr_id", "gr_line_id", "received_qty")];
    }
  }
  if (allErrors.length > 0) return { status: "Failed", allErrors: allErrors };

  // ---- code_pi_apply (v19) ----
  const absRound8 = (value) => {
    let positiveValue = Math.abs(value);
    return Math.round((parseFloat(positiveValue) || 0) * 100000000) / 100000000;
  };
  const qtyStr = (value) => absRound8(value).toFixed(8);
  const bundleKey = (row) => {
    const bundle = row.item_bundle_id;
    if (bundle && typeof bundle === "object") return String(bundle.id || bundle.ib_no || "");
    return String(bundle || "");
  };
  const flattenWithParent = (rows, itemKey) => {
    const flat = [];
    const positionOf = new Map();
    const isBundleRow = (row) => Boolean(bundleKey(row)) && !row[itemKey];
    const isBundleItem = (row) => Boolean(bundleKey(row)) && Boolean(row[itemKey]);
    let openBundle = -1;
    for (const [index, row] of (rows || []).entries()) {
      const position = flat.length;
      positionOf.set(index, position);
      const children = Array.isArray(row.children) ? row.children : [];
      if (children.length > 0) {
        openBundle = -1;
        flat.push({ row, parent: -1, nested: false });
        for (const child of children) flat.push({ row: child, parent: position, nested: true });
        continue;
      }
      if (isBundleRow(row)) {
        openBundle = position;
        flat.push({ row, parent: -1, nested: false });
        continue;
      }
      if (!isBundleItem(row)) {
        openBundle = -1;
        flat.push({ row, parent: -1, nested: false });
        continue;
      }
      let parent = -1;
      for (let candidate = index - 1; candidate >= 0; candidate--) {
        const candidateRow = rows[candidate];
        if (!isBundleRow(candidateRow)) continue;
        const byId = row.parent_id != null && candidateRow.id != null && String(row.parent_id) === String(candidateRow.id);
        const byKey = row.parent_fm_key != null && candidateRow.fm_key != null && String(row.parent_fm_key) === String(candidateRow.fm_key);
        if (byId || byKey) {
          parent = positionOf.get(candidate);
          break;
        }
      }
      if (parent === -1 && openBundle !== -1 && bundleKey(flat[openBundle].row) === bundleKey(row)) parent = openBundle;
      flat.push({ row, parent, nested: false });
    }
    return flat;
  };
  const flattenRowsP = (rows, itemKey) => flattenWithParent(rows, itemKey).map((item) => item.row);
  const processItems = (items, tablePi, docId, docIdKey, piLineIdKey, qtyKey) => {
    const filteredPI = flattenRowsP(tablePi, "material_id").filter((item) => item[docIdKey] === docId);
    const isGR = piLineIdKey === "gr_line_id";
    const distributedByRowId = {};
    if (isGR) {
      const combinedPIs = filteredPI.filter((pi) => (!pi.gr_line_id || pi.gr_line_id === "") && pi.po_line_id);
      for (const cpi of combinedPIs) {
        const groupRows = items.filter((r) => r.parent_or_child === "Split-Parent" && r.po_line_item_id === cpi.po_line_id)
          .sort((a, b) => String(a.line_index).localeCompare(String(b.line_index), undefined, { numeric: true }));
        let remainingToAllocate = absRound8(cpi.invoice_qty);
        for (const r of groupRows) {
          if (remainingToAllocate <= 0) break;
          const already = distributedByRowId[r.id] || 0;
          const capacity = absRound8((parseFloat(r.received_qty) || 0) - (parseFloat(r.invoice_qty) || 0) - already);
          if (capacity <= 0) continue;
          const alloc = Math.min(remainingToAllocate, capacity);
          distributedByRowId[r.id] = absRound8(already + alloc);
          remainingToAllocate = absRound8(remainingToAllocate - alloc);
        }
      }
    }
    // the invoice lines matched to each order / receipt line, grouped once (v19 filtered every line per line)
    const matchedBy = new Map();
    for (const pi of filteredPI) {
      const k = pi[piLineIdKey];
      if (!matchedBy.has(k)) matchedBy.set(k, []);
      matchedBy.get(k).push(pi);
    }
    const source = flattenWithParent(items, "item_id");
    const updated = source.map(({ row, parent }) => {
      const matchedPIs = matchedBy.get(row.id) || [];
      const directQty = matchedPIs.length > 0 ? absRound8(matchedPIs.reduce((s, pi) => s + (parseFloat(pi.invoice_qty) || 0), 0)) : 0;
      const distributedQty = distributedByRowId[row.id] || 0;
      const piInvoicedQty = absRound8(directQty + distributedQty);
      if (piInvoicedQty !== 0) {
        const currentInvoicedQty = absRound8(row.invoice_qty);
        const totalInvoicedQty = absRound8(currentInvoicedQty + piInvoicedQty);
        return { row: { ...row, invoice_qty: totalInvoicedQty }, parent };
      }
      return { row: { ...row }, parent };
    });
    let totalItems = 0;
    let partiallyInvoicedItems = 0;
    let fullyInvoicedItems = 0;
    for (const entry of updated) {
      if (entry.parent !== -1) continue;
